cd /tmp/vally-eval-trial-himqAB && P=.copilot-tracking/skraft-plans/pricing && D=2026-11-10 && mkdir -p $P/features $P/details/$D $P/evidence/$D/discount tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount
cat > $P/features/checkout-pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty discount at checkout
  As a returning customer
  I want my loyalty tier reflected in the checkout total
  So that the price I see rewards my history with the brand

  # SETTLED: AC-1, AC-2, AC-3 (values copied verbatim from ac.md).
  # NOT SETTLED: AC-4 (contradictory, see below) and the Platinum tier (no expected value exists).

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price for a basket
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price for a basket
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price for a basket
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  # OPEN DECISION (escalated to DISCUSS): AC-4 is titled "in the customer's favour" yet expects
  # 7 cents charged for a 7 cent subtotal. A 5% reduction of 7 cents is 0.35 cent: rounding it in
  # the customer's favour gives 1 cent off (6 charged), while 7 charged means no reduction at all.
  # Title and value contradict. The value is recorded verbatim; no test is authored and no
  # rounding rule is implied until the business states which outcome is intended.
  @edge-case @needs-decision
  Scenario: Bronze customer with a tiny basket is charged for a whole cent
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents

  # NOT DECIDED: Platinum tier. No scenario is written; the business has agreed no reduction.
E
